import java.util.*;

public class Hello {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine().trim();
        assert s.length() >= 1 && s.length() <= 8 : "Invalid input length";
        if (s.charAt(0) == '0') {
            System.out.println(s.length() > 1 ? "0" : "1");
            return;
        }
        int start = Integer.parseInt("1" + "0".repeat(s.length() - 1));
        if (start == 1) {
            start = 0;
        } else if (start == 10) {
            start = 25;
        }
        int end = Integer.parseInt("9".repeat(s.length()));
        int count = 0;
        for (int val = start; val <= end; val += 25) {
            if (checkPattern(val, s)) {
                count++;
            }
        }
        System.out.println(count);
    }

    private static boolean checkPattern(int num, String pattern) {
        String numStr = String.valueOf(num);
        char lastX = '*';
        for (int i = 0; i < pattern.length(); i++) {
            char pChar = pattern.charAt(i);
            if (pChar == '_') continue;
            if (pChar == 'X') {
                if (lastX != '*' && lastX != numStr.charAt(i)) return false;
                lastX = numStr.charAt(i);
            } else if (pChar != numStr.charAt(i)) {
                return false;
            }
        }
        return true;
    }
}
