#include <bits/stdc++.h>
using namespace std;

bool checkPattern(int num, const string& pattern) {
    string numStr = to_string(num);
    char lastX = '*';
    for (size_t i = 0; i < pattern.length(); i++) {
        char pChar = pattern[i];
        if (pChar == '_') continue;
        if (pChar == 'X') {
            if (lastX != '*' && lastX != numStr[i]) return false;
            lastX = numStr[i];
        } else if (pChar != numStr[i]) {
            return false;
        }
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    getline(cin, s);
    s.erase(s.begin(), find_if(s.begin(), s.end(), [](unsigned char ch){ return !isspace(ch); }));
    s.erase(find_if(s.rbegin(), s.rend(), [](unsigned char ch){ return !isspace(ch); }).base(), s.end());
    int len = s.length();
    assert(len >= 1 && len <= 8);
    if (s[0] == '0') {
        cout << (len > 1 ? "0" : "1") << "\n";
        return 0;
    }
    int start = stoi("1" + string(len - 1, '0'));
    if (start == 1) {
        start = 0;
    } else if (start == 10) {
        start = 25;
    }
    int end = stoi(string(len, '9'));
    int count = 0;
    for (int val = start; val <= end; val += 25) {
        if (checkPattern(val, s)) {
            count++;
        }
    }
    cout << count << "\n";
    return 0;
}
